import{_ as t,o as s,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-11-06（量子物理 · 三味哈伯德量子气体显微镜）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/quantum-physics/science-daily-2026-11-06-quantum.md","filePath":"topics/quantum-physics/science-daily-2026-11-06-quantum.md"}'),i={name:"topics/quantum-physics/science-daily-2026-11-06-quantum.md"};function c(r,o,a,l,d,g){return s(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-11-06-量子物理-·-三味哈伯德量子气体显微镜" tabindex="-1">科学日报 · 2026-11-06（量子物理 · 三味哈伯德量子气体显微镜） <a class="header-anchor" href="#科学日报-·-2026-11-06-量子物理-·-三味哈伯德量子气体显微镜" aria-label="Permalink to &quot;科学日报 · 2026-11-06（量子物理 · 三味哈伯德量子气体显微镜）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-06.md</code> — 第56期 ｜ 科学板块（量子向 1 篇） 落盘说明：文件名带 <code>-quantum</code> 后缀，避免与其它主题同日同名文件互引产生伪边。</p></blockquote><hr><h2 id="科学日报-2026-11-06-量子-·-1-1-把量子气体显微镜推进到「三味」费米子" tabindex="-1">科学日报 2026-11-06（量子 · 1/1）：把量子气体显微镜推进到「三味」费米子 <a class="header-anchor" href="#科学日报-2026-11-06-量子-·-1-1-把量子气体显微镜推进到「三味」费米子" aria-label="Permalink to &quot;科学日报 2026-11-06（量子 · 1/1）：把量子气体显微镜推进到「三味」费米子&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-06.md</code> ｜ DOI: 10.1126/science.adv1247 ｜ Science (2026)</p></blockquote><ul><li>问题：<strong>哈伯德模型</strong>是<strong>强关联多体物理</strong>的范式；加入<strong>额外的组分（味道）</strong> 会<strong>打破 SU(2) 对称性</strong>，理论上预测<strong>大量新奇量子相</strong>，但实验上<strong>缺少能把三味体系进到单格点分辨</strong>的探测手段。</li><li>方法：把<strong>量子气体显微镜（quantum gas microscopy）</strong> 拓展到<strong>三味费米晶格气体</strong>的哈伯德区，用<strong>格点 + 味道双重分辨</strong>的探测，直接绘制<strong>三味哈伯德模型的相图</strong>；并与<strong>数值关联簇展开（NLCE）</strong> 计算作对照。</li><li>结果（实测）： <ul><li>在低至<strong>隧穿能量尺度</strong>的温度下发现 <strong>味道选择性局域（flavor-selective localization）</strong> 与 <strong>选择性配对（selective pairing）</strong> 的迹象；</li><li>测量与 NLCE 计算在相图结构上相互印证；</li><li>指出<strong>继续提高相空间密度</strong>有望观测到<strong>半填充下的配对莫特相</strong>，并为研究<strong>色超流（color superfluidity）</strong> 乃至<strong>量子色动力学</strong>的其它面向开辟路径。</li></ul></li><li>洞察（对本库 <code>quantum-physics</code> × <code>physics</code>）： <ol><li><strong>「加一个新自由度，就打开一整片新相图」</strong>——从两味到三味不是量的叠加，而是<strong>对称性破缺带来的质变</strong>；判据：<strong>当既有体系『玩不出新花样』时，先问『能不能加入一个新守恒量/新味道』</strong>（呼应母题「<strong>约束-涌现</strong>」）。</li><li><strong>「单格点分辨 = 把理论相图搬进实验」</strong>——显微镜给的是<strong>逐格点、逐味道</strong>的实空间信息，才让『选择性局域/配对』这类<strong>局部</strong>现象变得可见；判据：<strong>要验证一个依赖局部关联的理论预言，先具备局部、可分辨的探测能力</strong>。</li><li><strong>与库内呼应</strong>：与同日 <code>topics/physics/science-daily-2026-11-06-physics.md</code>（铜氧化物赝能隙）、与 <code>topics/quantum-physics/</code> 的模拟—理论互证脉络同族。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/quantum-physics/index.md</code> ｜ <code>topics/physics/quantum-computing-deep.md</code> ｜ 第56期 科学板块</p></blockquote><p>关键词：科学日报第56期、量子气体显微镜quantum gas microscopy、三味费米子、三味哈伯德模型three-flavor Hubbard、SU(2)对称性破缺、味道选择性局域flavor-selective localization、选择性配对selective pairing、数值关联簇展开NLCE、配对莫特相pair Mott、色超流color superfluidity、量子色动力学QCD类比、格点与味道双分辨、加新自由度打开新相图、局部关联需要局部探测</p><p>关联：<code>topics/quantum-physics/index.md</code>、<code>topics/quantum-physics/science-daily-2026-11-05-quantum.md</code>、<code>topics/physics/science-daily-2026-11-06-physics.md</code>、<code>ScienceDaily/daily/2026-11-06.md</code></p>',10)])])}const m=t(i,[["render",c]]);export{p as __pageData,m as default};
